import type {RecordStats} from '@/types/seasonStats'; export function StatGrid({stats}: {stats:RecordStats}){return <div className="stat-grid">{[['試合',stats.matches],['勝利',stats.wins],['引分',stats.draws],['敗戦',stats.losses],['勝点',stats.points],['得点',stats.goalsFor],['失点',stats.goalsAgainst],['得失点差',stats.goalDifference>0?`+${stats.goalDifference}`:stats.goalDifference]].map(([l,v])=><div className="stat" key={l}><strong>{v}</strong><span>{l}</span></div>)}</div>}
