import type { Match, HomeAway } from '@/types/match'; import type { RecordStats, SeasonStats } from '@/types/seasonStats';
const record=(matches:Match[], place?:HomeAway):RecordStats=>{const done=matches.filter(m=>m.status==='FINISHED'&&m.score&&(!place||m.homeAway===place));const wins=done.filter(m=>m.result==='WIN').length,draws=done.filter(m=>m.result==='DRAW').length,losses=done.filter(m=>m.result==='LOSE').length;const goalsFor=done.reduce((n,m)=>n+(m.score?.kashima??0),0),goalsAgainst=done.reduce((n,m)=>n+(m.score?.opponent??0),0);return{matches:done.length,wins,draws,losses,points:wins*3+draws,goalsFor,goalsAgainst,goalDifference:goalsFor-goalsAgainst}};
export const calculateSeasonStats=(matches:Match[],season:number):SeasonStats=>{const selected=matches.filter(m=>m.season===season);return{season,...record(selected),home:record(selected,'HOME'),away:record(selected,'AWAY')}};
